#!/usr/bin/env python3
from pathlib import Path
import subprocess
import sys
import re

DASHBOARD = '\nimport json\nimport os\nimport signal\nimport subprocess\nimport sys\nfrom datetime import datetime\nfrom http.server import BaseHTTPRequestHandler, HTTPServer\nfrom pathlib import Path\nfrom urllib.parse import urlparse\n\nPID = Path("seed_dashboard_v106.pid")\nLOG = Path("seed_dashboard_v106.log")\nPORT = 8806\n\ndef now():\n    return datetime.now().isoformat(timespec="seconds")\n\ndef module_call(title, module, fn):\n    try:\n        m = __import__(module, fromlist=[fn])\n        data = getattr(m, fn)()\n        ok = bool(data.get("ok", True))\n        return {"title": title, "ok": ok, "data": data}\n    except Exception as e:\n        return {"title": title, "ok": False, "error": str(e), "data": {"ok": False, "error": str(e)}}\n\ndef gather():\n    cards = [\n        module_call("Supervisor OS", "seed_supervisor_v92", "supervisor_status"),\n        module_call("Wake Engine", "seed_wake_engine_v93", "status"),\n        module_call("Safety Ledger", "seed_safety_ledger_v94", "status"),\n        module_call("Trace / Errors", "seed_trace_v95", "status"),\n        module_call("Memory Garden 2", "seed_memory_garden2_v96", "status"),\n        module_call("Tool Bridge", "seed_tool_bridge_v97", "status"),\n        module_call("Vision", "seed_vision_v98", "status"),\n        module_call("Tasks", "seed_tasks_v99", "status"),\n        module_call("Operator", "seed_operator_v100", "status"),\n        module_call("Coder", "seed_coder_v101", "status"),\n        module_call("Voice", "seed_voice_v102", "status"),\n        module_call("Devices", "seed_device_body_v103", "status"),\n        module_call("Private RAG", "seed_private_rag_v104", "status"),\n        module_call("Doctor", "seed_doctor_v105", "diagnose"),\n    ]\n    ok_count = sum(1 for c in cards if c["ok"])\n    return {\n        "created_at": now(),\n        "version": "v106.1.0",\n        "ok": ok_count >= 10,\n        "ok_count": ok_count,\n        "total": len(cards),\n        "cards": cards,\n    }\n\ndef summarize_card(card):\n    data = card.get("data") or {}\n    title = card.get("title", "")\n    if title == "Supervisor OS":\n        return f"{len(data.get(\'cards\', []))} subsystem cards"\n    if title == "Wake Engine":\n        return f"Chosen: {data.get(\'chosen\', \'unknown\')}"\n    if title == "Safety Ledger":\n        settings = data.get("settings", {})\n        return f"Risk gates: risky requires approval = {settings.get(\'require_approval_risky\', True)}"\n    if title == "Trace / Errors":\n        return f"Trace {data.get(\'trace\', 0)} · Errors {data.get(\'errors\', 0)} · Actions {data.get(\'actions\', 0)}"\n    if title == "Memory Garden 2":\n        return f"Base memories: {data.get(\'base_memories\', 0)}"\n    if title == "Tool Bridge":\n        return f"{len(data.get(\'tools\', {}))} registered tools"\n    if title == "Vision":\n        ambient = data.get("ambient_vision", {})\n        alive = ambient.get("alive", False)\n        return "Ambient vision alive" if alive else "Vision available, not currently alive"\n    if title == "Tasks":\n        return f"{len(data.get(\'tasks\', []))} tasks"\n    if title == "Operator":\n        return "Mac actions gated by safety ledger"\n    if title == "Coder":\n        return f"Aider: {\'found\' if data.get(\'aider\') else \'not found\'}"\n    if title == "Voice":\n        s = data.get("settings", {})\n        return f"Mode {s.get(\'mode\', \'normal\')} · rate {s.get(\'rate\', \'?\')}"\n    if title == "Devices":\n        return f"{len(data.get(\'devices\', {}))} device(s)"\n    if title == "Private RAG":\n        return f"Indexed files: {data.get(\'indexed\', 0)}"\n    if title == "Doctor":\n        bad = [k for k, v in (data.get("checks", {}) or {}).items() if not v.get("ok")]\n        return "All checks green" if not bad else "Needs attention: " + ", ".join(bad)\n    return "Ready" if card.get("ok") else "Needs attention"\n\ndef view_model():\n    data = gather()\n    for card in data["cards"]:\n        card["summary"] = summarize_card(card)\n    return data\n\nHTML = \'\'\'<!doctype html>\n<html>\n<head>\n<meta charset="utf-8">\n<title>Seed Dashboard v106.1</title>\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<style>\n:root{--bg:#080808;--panel:#141414;--text:#f4f4f4;--muted:#a9a9a9;--orange:#ff8a23;--green:#65e88a;--red:#ff5d5d;--line:#2d2d2d}\n*{box-sizing:border-box}\nbody{margin:0;background:radial-gradient(circle at top left,#201103,#080808 42%);color:var(--text);font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","Segoe UI",sans-serif}\nheader{padding:28px 34px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;gap:18px;background:rgba(10,10,10,.72);backdrop-filter:blur(18px);position:sticky;top:0;z-index:10}\n.brand{display:flex;align-items:center;gap:15px}\n.orb{width:42px;height:42px;border-radius:50%;background:radial-gradient(circle at 35% 25%,#ffe0b6,#ff8a23 45%,#612400);box-shadow:0 0 36px rgba(255,138,35,.35);animation:pulse 3s ease-in-out infinite}\n@keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.07)}}\nh1{font-size:27px;margin:0}.sub{color:var(--muted);font-size:13px;margin-top:3px}\n.badge{border:1px solid var(--line);border-radius:999px;padding:8px 12px;background:#111;color:var(--muted);font-size:13px}\nmain{padding:28px 34px 48px}\n.hero{display:grid;grid-template-columns:1.25fr .75fr;gap:18px;margin-bottom:18px}\n.box{background:linear-gradient(180deg,var(--panel),#101010);border:1px solid var(--line);border-radius:22px;padding:20px;box-shadow:0 20px 70px rgba(0,0,0,.35)}\n.big{font-size:42px;font-weight:800;margin:8px 0}.muted{color:var(--muted)}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px}\n.card{background:var(--panel);border:1px solid var(--line);border-radius:18px;padding:17px;transition:.16s transform,.16s border-color}\n.card:hover{transform:translateY(-2px);border-color:#4a4a4a}\n.cardTop{display:flex;justify-content:space-between;align-items:start;gap:12px}\n.title{font-weight:750;font-size:17px}.status{font-size:12px;border-radius:999px;padding:5px 9px}\n.ok{color:#101;background:var(--green)}.bad{color:#180000;background:var(--red)}\n.summary{color:var(--muted);font-size:13px;line-height:1.35;margin:10px 0 14px;min-height:36px}\ndetails{border-top:1px solid var(--line);padding-top:10px}\nsummary{cursor:pointer;color:var(--orange);font-size:13px}\npre{white-space:pre-wrap;word-break:break-word;color:#d8d8d8;background:#0b0b0b;border:1px solid #262626;border-radius:12px;padding:12px;max-height:260px;overflow:auto;font-size:12px}\nbutton{background:#1d1d1d;border:1px solid #333;color:#eee;border-radius:11px;padding:9px 12px;cursor:pointer}\nbutton:hover{border-color:var(--orange)}\n@media(max-width:850px){.hero{grid-template-columns:1fr}header{align-items:flex-start;flex-direction:column}}\n</style>\n</head>\n<body>\n<header>\n  <div class="brand">\n    <div class="orb"></div>\n    <div>\n      <h1>Seed Dashboard</h1>\n      <div class="sub">v106.1 · Supervisor / Safety / Memory / Body / Tools</div>\n    </div>\n  </div>\n  <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap">\n    <button onclick="refresh()">Refresh</button>\n    <span id="stamp" class="badge">loading…</span>\n  </div>\n</header>\n<main>\n  <section class="hero">\n    <div class="box">\n      <div class="muted">System health</div>\n      <div id="score" class="big">—</div>\n      <div id="summary" class="muted">Reading Seed state…</div>\n    </div>\n    <div class="box">\n      <div class="muted">Quick commands</div>\n      <pre>python seed_mega_v92_106.py start\npython seed_mega_v92_106.py stop\npython seed_mega_v92_106.py doctor\npython seed_mega_v92_106.py eval</pre>\n    </div>\n  </section>\n  <section id="grid" class="grid"></section>\n</main>\n<script>\nfunction esc(x){return String(x ?? \'\').replace(/[&<>"\']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\\\\"":"&quot;","\'":"&#039;"}[m]))}\nasync function refresh(){\n  const res = await fetch(\'/api/status?ts=\' + Date.now());\n  const data = await res.json();\n  document.getElementById(\'stamp\').textContent = data.created_at;\n  document.getElementById(\'score\').textContent = data.ok_count + \'/\' + data.total + \' green\';\n  document.getElementById(\'summary\').textContent = data.ok ? \'Seed backbone is mostly healthy.\' : \'Some modules need attention. Open details below.\';\n  document.getElementById(\'grid\').innerHTML = data.cards.map(c => `\n    <article class="card">\n      <div class="cardTop">\n        <div class="title">${esc(c.title)}</div>\n        <div class="status ${c.ok ? \'ok\' : \'bad\'}">${c.ok ? \'OK\' : \'CHECK\'}</div>\n      </div>\n      <div class="summary">${esc(c.summary || \'\')}</div>\n      <details>\n        <summary>details</summary>\n        <pre>${esc(JSON.stringify(c.data || c.error || {}, null, 2))}</pre>\n      </details>\n    </article>\n  `).join(\'\');\n}\nrefresh();\nsetInterval(refresh, 4000);\n</script>\n</body>\n</html>\'\'\'\n\nclass Handler(BaseHTTPRequestHandler):\n    def send_bytes(self, code, body, ctype):\n        if isinstance(body, str):\n            body = body.encode("utf-8")\n        self.send_response(code)\n        self.send_header("Content-Type", ctype)\n        self.send_header("Cache-Control", "no-store, no-cache, must-revalidate, max-age=0")\n        self.send_header("Content-Length", str(len(body)))\n        self.end_headers()\n        self.wfile.write(body)\n\n    def do_GET(self):\n        path = urlparse(self.path).path\n        if path in ["/api/status", "/status"]:\n            self.send_bytes(200, json.dumps(view_model(), ensure_ascii=False), "application/json; charset=utf-8")\n        elif path in ["/", "/dashboard", "/index.html"]:\n            self.send_bytes(200, HTML, "text/html; charset=utf-8")\n        elif path == "/health":\n            self.send_bytes(200, json.dumps({"ok": True, "version": "v106.1.0"}), "application/json; charset=utf-8")\n        else:\n            self.send_bytes(404, "not found", "text/plain; charset=utf-8")\n\n    def log_message(self, *args):\n        return\n\ndef serve():\n    print(f"Seed dashboard v106.1: http://127.0.0.1:{PORT}/")\n    HTTPServer(("127.0.0.1", PORT), Handler).serve_forever()\n\ndef alive(pid):\n    try:\n        os.kill(int(pid), 0)\n        return True\n    except Exception:\n        return False\n\ndef start():\n    if PID.exists():\n        try:\n            pid = int(PID.read_text().strip())\n            if alive(pid):\n                subprocess.Popen(["open", f"http://127.0.0.1:{PORT}/?v=1061"])\n                return {"ok": True, "already_running": True, "pid": pid, "url": f"http://127.0.0.1:{PORT}/"}\n        except Exception:\n            pass\n\n    log = LOG.open("a")\n    proc = subprocess.Popen([sys.executable, "seed_dashboard_v106.py", "serve"], stdout=log, stderr=log)\n    PID.write_text(str(proc.pid))\n    subprocess.Popen(["open", f"http://127.0.0.1:{PORT}/?v=1061"])\n    return {"ok": True, "pid": proc.pid, "url": f"http://127.0.0.1:{PORT}/"}\n\ndef stop():\n    pid = None\n    stopped = False\n    if PID.exists():\n        try:\n            pid = int(PID.read_text().strip())\n            if alive(pid):\n                os.kill(pid, signal.SIGTERM)\n                stopped = True\n            PID.unlink(missing_ok=True)\n        except Exception:\n            pass\n    return {"ok": True, "stopped": stopped, "pid": pid}\n\ndef status():\n    return {"created_at": now(), "version": "v106.1.0", "ok": True, "alive": PID.exists(), "url": f"http://127.0.0.1:{PORT}/"}\n\nif __name__ == "__main__":\n    arg = sys.argv[1] if len(sys.argv) > 1 else "status"\n    if arg == "serve":\n        serve()\n    elif arg == "start":\n        print(json.dumps(start(), indent=4, ensure_ascii=False))\n    elif arg == "stop":\n        print(json.dumps(stop(), indent=4, ensure_ascii=False))\n    elif arg == "raw":\n        print(json.dumps(view_model(), indent=4, ensure_ascii=False))\n    else:\n        print(json.dumps(status(), indent=4, ensure_ascii=False))\n'
GATE = '\nimport json\nimport subprocess\nimport sys\nfrom pathlib import Path\nfrom datetime import datetime\n\ndef now():\n    return datetime.now().isoformat(timespec="seconds")\n\ndef run_gate():\n    checks = []\n    for module in ["seed_dashboard_v106.py", "seed_v1061_dashboard_gate.py"]:\n        proc = subprocess.run([sys.executable, "-m", "py_compile", module], capture_output=True, text=True, timeout=30)\n        checks.append({"module": module, "ok": proc.returncode == 0, "stderr": proc.stderr[-1000:]})\n\n    modules_ok = all(c["ok"] for c in checks)\n\n    try:\n        import seed_dashboard_v106 as dash\n        html_ok = "Seed Dashboard" in dash.HTML and "System health" in dash.HTML and "grid" in dash.HTML\n        api = dash.view_model()\n        api_ok = api.get("total", 0) >= 10 and "cards" in api\n        status_ok = dash.status().get("ok") is True\n        details = {"api_total": api.get("total"), "api_ok_count": api.get("ok_count"), "status": dash.status()}\n    except Exception as e:\n        html_ok = False\n        api_ok = False\n        status_ok = False\n        details = {"error": str(e)}\n\n    report = {\n        "created_at": now(),\n        "version": "v106.1.0",\n        "ready": modules_ok and html_ok and api_ok and status_ok,\n        "modules_ok": modules_ok,\n        "html_ok": html_ok,\n        "api_ok": api_ok,\n        "status_ok": status_ok,\n        "checks": checks,\n        "details": details,\n    }\n    Path("seed_v1061_dashboard_gate_report.json").write_text(json.dumps(report, indent=4, ensure_ascii=False))\n    return report\n\ndef show():\n    r = run_gate()\n    print("\\n=== SEED v106.1 DASHBOARD UI GATE ===")\n    print(f"Ready: {r[\'ready\']}")\n    print(f"Modules OK: {r[\'modules_ok\']}")\n    print(f"HTML OK: {r[\'html_ok\']}")\n    print(f"API OK: {r[\'api_ok\']}")\n    print(f"Status OK: {r[\'status_ok\']}")\n    print(f"Details: {r[\'details\']}")\n\nif __name__ == "__main__":\n    show()\n'

Path("seed_dashboard_v106.py").write_text(DASHBOARD.strip() + "\n")
print("Wrote seed_dashboard_v106.py")

Path("seed_v1061_dashboard_gate.py").write_text(GATE.strip() + "\n")
print("Wrote seed_v1061_dashboard_gate.py")

cfg = Path("seed_config.py")
text = cfg.read_text(errors="ignore") if cfg.exists() else 'SEED_VERSION = "v106.1.0"\n'
text = re.sub(r'^SEED_VERSION\s*=\s*".*?"', 'SEED_VERSION = "v106.1.0"', text, flags=re.M)
if "SEED_V1061_DASHBOARD_UI" not in text:
    text += "\nSEED_V1061_DASHBOARD_UI = True\n"
cfg.write_text(text)
print("Updated seed_config.py")

core = Path("Seed_Core.md")
ct = core.read_text(errors="ignore") if core.exists() else ""
if "Seed v106.1 — Dashboard UI Fix" not in ct:
    ct += """
## Seed v106.1 — Dashboard UI Fix

Replaces the raw JSON/pre dashboard with a real local web UI:
- Card grid for Seed subsystems.
- Health score.
- Details expandable per module.
- JSON API stays available at /api/status and /status.
- Root route `/` serves HTML with correct text/html content type.
"""
core.write_text(ct)
print("Updated Seed_Core.md")

for module in ["seed_dashboard_v106.py", "seed_v1061_dashboard_gate.py"]:
    proc = subprocess.run([sys.executable, "-m", "py_compile", module], capture_output=True, text=True, timeout=30)
    print("$ python -m py_compile", module)
    if proc.returncode == 0:
        print("OK")
    else:
        print(proc.stderr)
        sys.exit(proc.returncode)

print("\nSeed v106.1 Dashboard UI Fix installed.")
